import os
import re
import subprocess

from robot.api import ExecutionResult
from robot.result.visitor import ResultVisitor

from ..exception import EmptySuiteException
from ..report.builder import SuiteBuilder, TestBuilder
from ..report.parser import Scanner
from ..report.qc_migration import (
    set_automation_options_data_from_scratch,
    should_automation_options_be_set,
)
from ..report.testdata import TEST_STRUCTURE
from ..robot_compatibility import (
    get_suite_setup_keyword,
    get_suite_teardown_keyword,
)
from ..utils.encoder import shorten_text
from ..utils.logger import logger
from ..utils.tags import get_single_tag_from_test
from ..utils.variables import get_json_env_variable_value


def collect(collector, environment):
    """
    Function for collecting suite data using Collector instance

    :param collector        collector:      ResultVisitor custom instance for collecting Robot output data.
    :param environment      environment:    Environment variables class instance.
    """
    exec_result = ExecutionResult(environment.robot_output)
    try:
        exec_result.visit(collector)
    except AttributeError as e:
        logger.error(repr(e))
    try:
        collector.prepare_result()
        return collector
    except EmptySuiteException:
        if environment.ignore_empty_suites:
            logger.error(
                "[FAIL] Report action was run on empty suite/non-existent suite."
            )
            return collector
        raise


class ResultCollector(ResultVisitor):
    """
    Create the JSON file with data for Reporting Portal based on the output.xml file generated by the
    Robot Framework.
    """

    def __init__(self, environment, test_line):
        self._result = []
        self._test_builder = TestBuilder(test_line, environment)
        self._suite_builder = SuiteBuilder(environment)
        self._dynamic_qc_file_path = None
        self._config_list = None
        self._robot_file_path = environment.suite_path
        self._suite_source = environment.suite_path
        self._suite_source_abs_path = ""
        self._bts_sw_version = environment.sw_version or test_line.bts_sw_version
        self._ap_version = (
            environment.ap_version
            or self._test_builder.simulators["airphone"]["version"]
        )
        self._tool = environment.tool or None
        self._label = environment.label
        self._ute_version = environment.ute_version
        self._fail_cause = environment.fail_cause or None
        self._env_issue = environment.env_issue or None
        self._no_qc = environment.no_qc
        self._cu_build = environment.cu_build
        self._cu_caas_build = environment.cu_caas_build
        self._du_caas_build = environment.du_caas_build
        self._fhgw_build = environment.fhgw_build
        self._enb_nsa_build = environment.enb_nsa_build
        self._gnb_nsa_build = environment.gnb_nsa_build
        self._customers = environment.customers
        self._rf_sw_line = environment.rf_sw_line
        self._rf_sw_branch = environment.rf_sw_branch
        self._gnb_rf_shared_build = environment.gnb_rf_shared_build
        self._enb_rf_shared_build = environment.enb_rf_shared_build
        self._bts2g_rf_shared_build = environment.bts2g_rf_shared_build
        self._nb_rf_shared_build = environment.nb_rf_shared_build
        self._html_log_link = environment.links.get("Test logs")
        self._executed_test_loops = environment.executed_test_loops
        self.suite_empty = False
        self.summary = {}
        self._suite_name = ""

    @property
    def result(self):
        """Return the visiting result without empty tests."""
        return self._result

    @property
    def dynamic_qc_file_path(self):
        """Return QC file path set during execution."""
        return self._dynamic_qc_file_path

    @property
    def suite_source(self):
        """Return suite path set during execution."""
        return self._suite_source

    def prepare_result(self):
        """Return the visiting result without empty tests."""
        self._remove_empty_suites()
        if not self._result:
            self.suite_empty = True
            raise EmptySuiteException(
                "[FAIL] Report action was run on empty suite/non-existent suite."
            )

    def start_suite(self, suite):
        """Method invoked when a suite section starts."""
        self._suite_source = (
            self._robot_file_path
            if self._robot_file_path and os.path.isfile(self._robot_file_path)
            else suite.source
        )
        if not os.path.isdir(self._suite_source) and os.path.exists(self._suite_source):
            self._suite_source_abs_path = os.path.realpath(self._suite_source)
        else:
            logger.debug(
                f"Path to suite: {self._suite_source}\n non-existent or is a directory. "
                "Skipping this suite/searching deeper in a directory tree"
            )
        self._test_scanner = Scanner()
        logger.debug(f"[Start] Suite: {suite.name}")
        self._suite_name = suite.name
        self._suite_builder.enter_suite(suite.name)
        self._result.append(self._suite_builder.build(suite))
        self._set_tool_for_suite(suite)
        self._set_rtg_build_for_suite(
            suite, predefined=self._test_builder.simulators["rtg"]["version"]
        )
        self._set_ute_version()
        self._set_label_for_suite()
        self._add_cm_sign_data()
        self._add_cm_artifacts_data()
        self._add_cm_execution_id()
        self._add_cm_tags()
        self._set_fail_cause_for_suite()
        self._set_env_issue_for_suite()
        self._set_suite_setup_teardown_exceptions(suite)
        self._set_suite_metadata_for_symptom_files(suite)

    def start_test(self, test):  # noqa: C901
        """Method invoked when a test section starts."""
        if self._result:
            current_suite = self._result[-1]
            if "SKIP_REPORT" in list(test.tags):
                logger.debug(f"[Start] Test will be skipped: {test.name}")
                self.summary.update({test.name: ["[ Skipped]", "[ No QC ]"]})
                return
            logger.debug(f"[Start] Test: {test.name}")
            test_data = self._test_builder.build_data(
                test,
                suite_prefix=self._suite_builder.get_suite_prefix(),
                test_case_names_in_automation_options=self._suite_builder.test_case_names_in_automation_options
            )
            if isinstance(test_data, tuple) and test_data[0] == "skip":
                logger.debug(f'TEST: "{test_data[1]}", has been skipped')
                return
            test_data.counter_results = self._test_scanner.scan_for_counters(test)
            test_data.kpi_results = self._test_scanner.scan_for_kpi_results(test)
            self._set_test_metadata_for_symptom_files(test, test_data)
            test_data.system_under_test = self._test_scanner.scan_for_system_under_test(
                test
            )
            test_data.steps = self._test_scanner.scan_for_steps(test)
            test_data.hw_config = self._test_scanner.scan_for_hw_config(test)
            test_data.tc_execution_id = self._get_tc_execution_id(test)
            self._set_bts_sw_build_and_tag(test, test_data)
            test_data.airphone = (
                self._test_scanner.scan_for_ap_version(test) or self._ap_version
            )
            self._set_test_exceptions(test, test_data, current_suite)
            test_data.cu_build = self._cu_build
            test_data.cu_caas_build = self._cu_caas_build
            test_data.du_caas_build = self._du_caas_build
            test_data.fhgw_build = self._fhgw_build
            test_data.enb_nsa_build = self._enb_nsa_build
            test_data.gnb_nsa_build = self._gnb_nsa_build
            test_data.gnb_rf_shared_build = self._gnb_rf_shared_build
            test_data.enb_rf_shared_build = self._enb_rf_shared_build
            test_data.bts2g_rf_shared_build = self._bts2g_rf_shared_build
            test_data.nb_rf_shared_build = self._nb_rf_shared_build
            test_data.customers = self._customers
            test_data.rf_sw_line = self._rf_sw_line
            test_data.rf_sw_branch = self._rf_sw_branch
            test_data.ref_configuration_id = (
                self._test_scanner.scan_for_reference_configuration_id(test)
            )
            if should_automation_options_be_set():
                test_data.automation_options = set_automation_options_data_from_scratch(
                    test.name, self._suite_source_abs_path, test.timeout
                )
            test_data.test_loops = (
                self._executed_test_loops
            )  # For historical reasons, we reuse the existing 'test_loops' field in the ReP API

            test_data.suite_path = str(self._robot_file_path) or str(self._suite_source)
            mapped_test_name = self._test_scanner.get_testcase_name(test)
            if mapped_test_name:
                test_data.qc_test_instance_name = mapped_test_name
            dynamic_qc_file_path = self._test_scanner.scan_for_qc_file(test)
            if dynamic_qc_file_path and self._dynamic_qc_file_path is None:
                logger.debug(
                    f"Looking for QC configuration in external config file: {dynamic_qc_file_path[0]}"
                )
                self._dynamic_qc_file_path = dynamic_qc_file_path[0]
            tool_name = self._test_scanner.scan_for_tool(test)
            if tool_name:
                current_suite["tool"] = tool_name[-1]
            current_suite["test_cases"].append(test_data)

            self._add_extra_data(test, test_data)
        else:
            logger.debug("Entered empty test, searching for tests is skipped")

    def end_suite(self, suite):
        """Method invoked when a suite section ends."""
        logger.debug(f"[End] Suite: {suite.name}")
        self._suite_builder.exit_suite()

    def update_summary(self):
        """Update information about QC match/not match per test"""
        for suite in self.result:
            for test in suite["test_cases"]:
                if (
                    test["qc_test_instance_name"]
                    and test["qc_testlab_path"]
                    and test["qc_test_set_name"]
                ) or test["qc_id"]:
                    self.summary.update({test["name"]: ["[Reported]", "[With QC]"]})
                else:
                    self.summary.update({test["name"]: ["[Reported]", "[ No QC ]"]})

    def _remove_empty_suites(self):
        return [res for res in self._result if len(res["test_cases"])]

    def _set_tool_for_suite(self, suite):
        if self._tool:
            self._result[-1]["tool"] = self._tool
            return
        for test in suite.tests:
            tool_name = self._test_scanner.scan_for_tool(test)
            if tool_name:
                self._result[-1]["tool"] = tool_name[-1]
                return
        else:
            self._result[-1]["tool"] = "Robot"

    def _set_rtg_build_for_suite(self, suite, predefined=""):
        self._result[-1]["rtg_build"] = predefined
        for test in suite.tests:
            rtg_build = self._test_scanner.scan_for_rtg_build(test)
            if rtg_build:
                self._result[-1]["rtg_build"] = rtg_build
                return

    def _set_ute_version(self):
        ute_version = (
            self._ute_version if self._ute_version else self._get_ute_version()
        )
        self._result[-1]["ute_version"] = ute_version

    def _get_ute_version(self):
        package_check_cmd = "dpkg -s ute | awk '/^Version:/{print $2}'"
        ret = subprocess.Popen(
            package_check_cmd,
            stdout=subprocess.PIPE,
            shell=True,
            stderr=subprocess.PIPE,
        )
        version, error = ret.communicate()
        if "not installed" in str(error):
            logger.debug("No UTE Package installed")
            return
        return version

    def _set_label_for_suite(self):
        self._result[-1]["label"] = self._label

    def _add_cm_sign_data(self):
        cm_sign = get_json_env_variable_value("CM_SIGN", {})
        self._result[-1]["cm_sign"] = cm_sign

    def _add_cm_artifacts_data(self):
        cm_artifacts = get_json_env_variable_value("CM_ARTIFACTS", [])
        self._result[-1]["cm_artifacts"] += cm_artifacts

    def _add_cm_execution_id(self):
        cm_execution_id = os.getenv("CM_EXECUTION_ID", "")
        self._result[-1]["cm_execution_id"] = cm_execution_id

    def _add_cm_tags(self):
        cm_tags = get_json_env_variable_value("CM_TAGS", [])
        self._result[-1]["cm_tags"] += cm_tags

    def _get_tc_execution_id(self, test):
        tc_execution_id = get_single_tag_from_test(test, "TC_ID")
        return tc_execution_id

    def _set_fail_cause_for_suite(self):
        self._result[-1]["fail_cause"] = self._fail_cause

    def _set_env_issue_for_suite(self):
        self._result[-1]["env_issue"] = self._env_issue

    def _set_suite_setup_teardown_exceptions(self, suite):
        setup_exception, setup_exception_message = (
            self._check_for_suite_setup_teardown_exceptions(suite, "setup")
        )
        teardown_exception, teardown_exception_message = (
            self._check_for_suite_setup_teardown_exceptions(suite, "teardown")
        )
        self.result[-1]["setup_exception"] = setup_exception
        self.result[-1]["setup_exception_message"] = setup_exception_message
        self.result[-1]["teardown_exception"] = teardown_exception
        self.result[-1]["teardown_exception_message"] = teardown_exception_message

    def _check_for_suite_setup_teardown_exceptions(self, suite, phase):
        exc_type, exc_message = "", ""
        phase_keyword = (
            get_suite_setup_keyword(suite)
            if phase == "setup"
            else get_suite_teardown_keyword(suite)
        )
        if phase_keyword and phase_keyword.status == "FAIL":
            exc_type, exc_message = self._extract_type_and_message(
                phase_keyword.message
            )
            if exc_type == "" and exc_message == "":
                exc_type, exc_message = (
                    self._extract_type_and_message_from_suite_message(
                        suite.message, phase
                    )
                )
        return exc_type, exc_message

    @staticmethod
    def _extract_type_and_message(exception_message):
        exc_type = exception_message.split(":")[0]
        exc_message = exception_message.split(":", 1)[-1].strip()
        return exc_type, exc_message

    def _extract_type_and_message_from_suite_message(self, message, phase):
        fail_message = f"Suite {phase} failed:"
        exception_message = message.split(fail_message)[-1].strip()
        exc_type, exc_message = self._extract_type_and_message(exception_message)
        exc_message = shorten_text(exc_message)
        return exc_type, exc_message

    def _set_test_exceptions(self, test, test_data, suite):
        test_exceptions = self._test_scanner.scan_for_exceptions(test)
        suite_exceptions = {k: v for k, v in suite.items() if "exception" in k}
        test_data["test_exception"] = test_exceptions["test_exception"]
        test_data["test_exception_message"] = test_exceptions["test_exception_message"]
        if suite_exceptions["setup_exception"]:
            test_data["setup_exception"] = suite_exceptions["setup_exception"]
            test_data["setup_exception_message"] = suite_exceptions[
                "setup_exception_message"
            ]
            return
        test_data["setup_exception"] = test_exceptions["setup_exception"]
        test_data["setup_exception_message"] = test_exceptions[
            "setup_exception_message"
        ]
        if (
            suite_exceptions["teardown_exception"]
            and not test_exceptions["teardown_exception"]
        ):
            test_data["teardown_exception"] = suite_exceptions["teardown_exception"]
            test_data["teardown_exception_message"] = suite_exceptions[
                "teardown_exception_message"
            ]
        else:
            test_data["teardown_exception"] = test_exceptions["teardown_exception"]
            test_data["teardown_exception_message"] = test_exceptions[
                "teardown_exception_message"
            ]

    def _set_bts_sw_build_and_tag(self, test, test_data):
        bts_sw_version = self._test_scanner.scan_for_bts_sw_version(test)
        bts_sw_version = bts_sw_version if bts_sw_version else self._bts_sw_version
        if ":" not in bts_sw_version or bts_sw_version.split(":")[1] == "base":
            test_data.build = bts_sw_version.split(":")[0]
        else:
            test_data.build = bts_sw_version.split(":")[0]
            test_data.build_tag = bts_sw_version.split(":")[1]

    def _add_extra_data(self, test, test_data):
        extra_data = self._test_scanner.scan_for_extra_data(test)
        for key, value in extra_data.items():
            if key not in TEST_STRUCTURE:
                test_data.update({key: value})

    def _set_test_metadata_for_symptom_files(self, test, test_data):
        snapshot_locations = (
            self._test_scanner.scan_for_snapshot_location_in_test_keywords(test)
        )
        syslog_locations = self._test_scanner.scan_for_syslog_location_in_test_keywords(
            test
        )
        metadata = test_data.metadata_for_symptom_files
        if snapshot_locations or syslog_locations:
            metadata["root"] = {"href": self._get_root_log_dir()}
        if snapshot_locations:
            metadata["snapshots"] = snapshot_locations
        if syslog_locations:
            metadata["syslogs"] = syslog_locations

    def _set_suite_metadata_for_symptom_files(self, suite):
        snapshot_locations = self._test_scanner.scan_for_snapshot_location_in_suite_setup_and_teardown_keywords(
            suite
        )
        syslog_locations = self._test_scanner.scan_for_syslog_location_in_suite_setup_and_teardown_keywords(
            suite
        )
        metadata = self._result[-1]["metadata_for_symptom_files"]
        if snapshot_locations or syslog_locations:
            metadata["root"] = {"href": self._get_root_log_dir()}
        if snapshot_locations:
            metadata["snapshots"] = snapshot_locations
        if syslog_locations:
            metadata["syslogs"] = syslog_locations

    def _get_root_log_dir(self):
        # if ends with .html then return link to directory
        # if ends with .zip(or other extension) then return full link
        # if log_link is directory then return full link
        if self._html_log_link:
            return re.sub(r"/[^/]*.html", "", self._html_log_link)
